let liked={};function smash(i){liked[i]=!liked[i];renderFeed();notify(liked[i]?'Smashed match!':'Removed smash');}function renderFeed(){document.getElementById('feedCards').innerHTML=games.map((g,i)=>`<article class="glass rounded-3xl p-5"><div class="flex justify-between items-start"><div class="flex gap-3"><div class="w-11 h-11 rounded-2xl ${g.color} grid place-items-center font-extrabold text-sm">${g.initials}</div><div><div class="font-bold">${g.name}</div><div class="text-xs text-slate-500 mt-1">${g.time} · Pikol App</div></div></div><button class="text-slate-400 p-2" onclick="notify('More match options')"><i data-lucide="more-horizontal" class="w-5 h-5"></i></button></div><div class="mt-4 rounded-2xl bg-slate-50 p-4 flex justify-between items-center"><div><div class="text-[11px] text-slate-500">DEFEATED · ${g.against}</div><div class="text-2xl font-black tracking-tight mt-1">${g.score}</div><div class="text-xs text-slate-500 mt-1">${g.duration} <span class="mx-1">·</span> Doubles</div></div><div class="text-right"><div class="text-[10px] text-slate-400 uppercase tracking-wider">DUPR change</div><div class="font-extrabold text-emerald-700 mt-1">${g.delta}</div></div></div><div class="flex items-center gap-2 mt-4"><span class="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 text-emerald-700 px-2.5 py-1 text-[10px] font-bold"><i data-lucide="map-pin-check-inside" class="w-3 h-3"></i> GEOFENCE VERIFIED</span><span class="text-[10px] text-slate-400">Match confirmed at venue</span></div><div class="flex border-t border-slate-100 mt-4 pt-3 gap-2"><button class="flex-1 rounded-xl py-2.5 text-sm font-bold hover:bg-emerald-50 ${liked?.[i]?'text-emerald-700':'text-slate-600'}" onclick="smash(${i},this)"><i data-lucide="thumbs-up" class="inline w-4 h-4 mr-1 align-[-3px]"></i> Smash <span>${liked?.[i]?'1':''}</span></button><button class="flex-1 rounded-xl py-2.5 text-sm font-semibold text-slate-500 hover:bg-slate-50" onclick="openComments('${g.name}')"><i data-lucide="message-circle" class="inline w-4 h-4 mr-1 align-[-3px]"></i> Comment</button></div></article>`).join('');icons()}
