function moneyFmt(value){return '₱'+(Number(value)||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}
// (2026-07-13) Split checklist & booking dropdown; was simple stepper & select
let activeSplitContext='Pikol Pickle Hub · Court 1 (K-1042)';
let activeSplitOrderId='K-1042';
let splitPlayersList=[
  {name:'Alex R.',paid:true},
  {name:'Carlo M.',paid:false},
  {name:'Bea S.',paid:false},
  {name:'Dan T.',paid:false}
];
function ensureSplitPlayers(count){
  while(splitPlayersList.length<count){
    const idx=splitPlayersList.length+1;
    splitPlayersList.push({name:`Player ${idx}`,paid:false});
  }
  if(splitPlayersList.length>count){
    splitPlayersList=splitPlayersList.slice(0,count);
  }
}
function renameSplitPlayer(index,name){
  if(splitPlayersList[index]){
    splitPlayersList[index].name=name.trim()||`Player ${index+1}`;
  }
}
function renameSplitPlayerDraft(index,name){
  if(splitPlayersList[index]){
    splitPlayersList[index].name=name;
  }
}
function togglePlayerPaid(index){
  if(splitPlayersList[index]){
    splitPlayersList[index].paid=!splitPlayersList[index].paid;
    updateSplitBill(false);
  }
}
// (2026-07-13) Add/delete player & keyboard handlers; was count stepper only
function addSplitPlayer(){
  const count=splitPlayersList.length+1;
  splitPlayersList.push({name:`Player ${count}`,paid:false});
  const input=document.getElementById('splitPlayerCount');
  if(input)input.value=String(count);
  updateSplitBill(false);
  setTimeout(()=>{
    const fields=document.querySelectorAll('#splitPlayerRows .split-player-name-field');
    const last=fields[fields.length-1];
    if(last){last.focus();last.select();}
  },50);
}
function deleteSplitPlayer(index){
  if(splitPlayersList.length<=1){
    notify('At least one player is required');
    return;
  }
  const deleted=splitPlayersList.splice(index,1);
  const count=splitPlayersList.length;
  const input=document.getElementById('splitPlayerCount');
  if(input)input.value=String(count);
  updateSplitBill(false);
  setTimeout(()=>{
    const fields=document.querySelectorAll('#splitPlayerRows .split-player-name-field');
    const targetIdx=Math.max(0,index-1);
    if(fields[targetIdx]){fields[targetIdx].focus();fields[targetIdx].select();}
  },50);
  notify(`Removed ${deleted[0]?.name||'player'}`);
}
function handlePlayerKey(event,index){
  if(event.key==='Enter'){
    event.preventDefault();
    addSplitPlayer();
  }else if(event.key==='Backspace'&&event.target.value===''){
    event.preventDefault();
    deleteSplitPlayer(index);
  }
}
