function updateSplitPills(n){
  // (2026-07-13) Match numeric or text split-pill active state; was prefix only
  document.querySelectorAll('.split-pill').forEach(btn=>{
    btn.classList.toggle('active',btn.textContent.trim()===String(n)||btn.textContent.trim().startsWith(n+' '));
  });
}
function updateSplitBill(preserveFocus=true){
  const total=Math.max(0,parseFloat(document.getElementById('splitCourtAmount')?.value)||0);
  const count=Math.max(1,Math.min(40,parseInt(document.getElementById('splitPlayerCount')?.value)||1));
  ensureSplitPlayers(count);
  const share=count>0?total/count:0;
  const ctx=activeSplitContext||'Custom bill split';
  const set=(id,val)=>{const el=document.getElementById(id);if(el)el.textContent=val};
  set('splitTotalDisplay',moneyFmt(total));
  set('splitPerPerson',moneyFmt(share));
  set('splitContext',ctx);
  set('splitShareCaption',`${moneyFmt(total)} ÷ ${count} ${count===1?'player':'players'}`);
  const unit=document.getElementById('splitPlayerCountLabel');
  if(unit)unit.textContent='PLAYERS';
  const matchChip=document.getElementById('splitMatchChip');
  if(matchChip){
    matchChip.textContent=count===2?'Singles Match':count===4?'Doubles Match':`${count} Players`;
  }
  const paidCount=splitPlayersList.filter(p=>p.paid).length;
  const remainingAmt=Math.max(0,total-(paidCount*share));
  set('splitPaidCountLabel',`${paidCount} of ${count} Paid`);
  set('splitRemainingLabel',`${moneyFmt(remainingAmt)} remaining`);
  const progressFill=document.getElementById('splitProgressFill');
  if(progressFill){
    const pct=count>0?Math.round((paidCount/count)*100):0;
    progressFill.style.width=`${pct}%`;
  }
  const rows=document.getElementById('splitPlayerRows');
  if(rows){
    const focusedIndex=document.activeElement?.dataset?.playerIndex;
    // (2026-07-13) Add delete btn & keydown handlers; was no delete or key support
    rows.innerHTML=splitPlayersList.map((p,i)=>`
      <div class="split-player-row ${p.paid?'is-paid':''}">
        <button type="button" class="split-check-box ${p.paid?'checked':''}" onclick="togglePlayerPaid(${i})" aria-label="Mark ${p.name} as ${p.paid?'unpaid':'paid'}">${p.paid?'<i data-lucide="check"></i>':''}</button>
        <div class="split-player-info-wrap">
          <input type="text" class="split-player-name-field" data-player-index="${i}" value="${p.name}" oninput="renameSplitPlayerDraft(${i},this.value)" onchange="renameSplitPlayer(${i},this.value)" onkeydown="handlePlayerKey(event,${i})" aria-label="Player ${i+1} name" placeholder="Player ${i+1}">
          ${i===0?'<span class="split-host-tag">(Host)</span>':''}
        </div>
        <button type="button" class="split-status-pill ${p.paid?'paid':'unpaid'}" onclick="togglePlayerPaid(${i})">${p.paid?'PAID':'UNPAID'}</button>
        <b class="split-player-amount">${moneyFmt(share)}</b>
        <!-- (2026-07-13) Remove split-send-btn; was remind button on row -->
        <button type="button" class="split-delete-btn" onclick="deleteSplitPlayer(${i})" title="Delete ${p.name}" aria-label="Delete ${p.name}"><i data-lucide="trash-2"></i></button>
      </div>
    `).join('');
    icons();
    if(preserveFocus&&focusedIndex!==undefined){
      const el=rows.querySelector(`input[data-player-index="${focusedIndex}"]`);
      if(el){
        el.focus();
        if(selectionStart!==null&&selectionStart!==undefined)el.setSelectionRange(selectionStart,selectionStart);
      }
    }
  }
}
