function slideCarousel(containerId,dir){const el=document.getElementById(containerId);if(!el)return;const cards=el.querySelectorAll('article');if(!cards.length)return;const cardWidth=cards[0].offsetWidth+14;const activeIdx=Math.min(cards.length-1,Math.max(0,Math.round(el.scrollLeft/cardWidth)));let nextIdx=activeIdx+dir;if(nextIdx<0)nextIdx=cards.length-1;else if(nextIdx>=cards.length)nextIdx=0;scrollCarouselToIndex(containerId,nextIdx)}
