function scrollCarouselToIndex(containerId,index){const el=document.getElementById(containerId);if(!el)return;const cards=el.querySelectorAll('article');if(cards[index]){cards[index].scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'})}}
function syncCarouselDots(containerId,dotsId){const el=document.getElementById(containerId),dotsEl=document.getElementById(dotsId);if(!el||!dotsEl)return;const cards=el.querySelectorAll('article');if(!cards.length)return;const scrollLeft=el.scrollLeft,cardWidth=cards[0].offsetWidth+14,activeIdx=Math.min(cards.length-1,Math.max(0,Math.round(scrollLeft/cardWidth)));const dots=dotsEl.querySelectorAll('.carousel-dot');dots.forEach((d,i)=>{if(i===activeIdx)d.classList.add('active');else d.classList.remove('active')})}
function renderVenueCommunity(ownerId){const target=document.getElementById('venueCommunityCards'),section=document.getElementById('venueCommunitySection');if(!target)return;const owner=venueById(ownerId);if(!owner){if(section)section.style.display='none';return}const venuePlays=openPlayEvents.filter(x=>x.owner===ownerId||(x.venue&&x.venue.toLowerCase().includes(owner.name.toLowerCase()))),venuePasalos=pasaloOffers.filter(x=>x.owner===ownerId||(x.venue&&x.venue.toLowerCase().includes(owner.name.toLowerCase())));const heading=document.getElementById('venueCommunityHeading'),sub=document.getElementById('venueCommunitySub');if(heading)heading.textContent=`${owner.name} Community`;if(sub)sub.textContent=`${venuePlays.length} open play · ${venuePasalos.length} pasalo offers`;if(!venuePlays.length&&!venuePasalos.length){target.innerHTML=`<div class="rounded-2xl bg-slate-50 p-6 text-center text-xs text-slate-500 font-medium">No open plays or pasalo offers currently listed for ${owner.name}.</div>`;if(section)section.style.display='';return}let html='';if(venuePlays.length){html+=`<div class="mb-2"><span class="text-[11px] font-black uppercase tracking-wider text-emerald-800">Open Plays at this Court</span></div><div class="discovery-scroller community-openplay-list mb-4">${venuePlays.map(e=>openPlayCard(e)).join('')}</div>`}if(venuePasalos.length){html+=`<div class="mb-2"><span class="text-[11px] font-black uppercase tracking-wider text-emerald-800">Pasalo Transfers at this Court</span></div><div class="discovery-scroller community-pasalo-list">${venuePasalos.map(e=>pasaloCard(e)).join('')}</div>`}target.innerHTML=html;if(section)section.style.display='';icons()}
function renderCommunityDiscovery(){const h=document.getElementById('openPlayCards'),p=document.getElementById('pasaloCards'),hc=document.getElementById('openPlayCommunity'),pc=document.getElementById('pasaloCommunity');if(h)h.innerHTML=openPlayEvents.map(e=>openPlayCard(e)).join('');if(p)p.innerHTML=pasaloOffers.map(e=>pasaloCard(e)).join('');if(hc)hc.innerHTML=openPlayEvents.map(e=>openPlayCard(e,true)).join('');if(pc)pc.innerHTML=pasaloOffers.map(e=>pasaloCard(e,true)).join('');initCarouselControls('openPlayCards','openPlayDots',openPlayEvents.length);initCarouselControls('pasaloCards','pasaloDots',pasaloOffers.length);icons()}function joinOpenPlay(id){const x=openPlayEvents.find(e=>e.id===id);if(!x)return;if(joinedOpenPlays.has(id)){joinedOpenPlays.delete(id);notify('Left Open Play · demo')}else{joinedOpenPlays.add(id);notify(`Spot reserved · ${x.venue} · demo`)}renderCommunityDiscovery()}function requestPasalo(id){const x=pasaloOffers.find(e=>e.id===id);if(!x)return;if(requestedPasalo.has(id)){notify('Transfer request already sent · demo');return}requestedPasalo.add(id);renderCommunityDiscovery();notify(`Transfer request sent to the court owner · ${x.venue} · demo`)}function toggleSaveOpenPlay(id,button){button.classList.toggle('saved');button.innerHTML=`<i data-lucide="${button.classList.contains('saved')?'bookmark-check':'bookmark'}"></i>`;icons()}
